// Small, deliberately named teaching modules; these are not built-in plugins.
const prepPanel=(label,text,state='active')=>({label,items:[{text,state}]});
const prepFrame=(title,explain,why,focus,label,text,highlight,panels,result)=>({title,explain,why,focus,code:{label,language:'go',text,highlight},panels,result});
const prepFrames=[
  prepFrame('先看原来的房间服务','你写了一个查房间的程序。现在只认识自己的 room 包，还没有观察调用的代码。','自动插桩最后要调用记录函数；记录函数也要和业务代码一起编译。',0,'原来的 main.go · 教学片段','import "example.com/room"\n\nfunc main() {\n    room.FindRoom(42)\n}',[1,4],[prepPanel('目前参与构建','main → room'),prepPanel('已经选中的规则','空集合 []','muted'),prepPanel('还没接入的记录包','room-recorder、cache-recorder','muted')],'现在直接 go build，只会得到原来的业务程序。'),
  prepFrame('准备①：先接入基础记录库','newDeps 收到的规则集合还是空的；它先生成基础 import，再由 syncDeps 整理依赖。','LoongSuite 自己也要改写部分 OTel 代码，所以第一次找规则前，要先让基础记录库进入构建范围。',0,'otel.runtime.go · 省略其他基础 import','package main\n\nimport _ "github.com/alibaba/loongsuite-go/pkg"\nimport _ "go.opentelemetry.io/otel"\nimport _ "go.opentelemetry.io/otel/sdk/trace"',[3,4,5],[prepPanel('新进入构建的代码','基础 OTel / SDK','new'),prepPanel('规则集合','仍是 []','muted'),prepPanel('本轮执行','newDeps([]) → syncDeps()')],'基础库准备好了；具体用哪个业务记录包，要等下一步匹配。'),
  prepFrame('匹配①：发现 room.FindRoom 可以观察','扫描现在会参与构建的包，找到教学规则：在 FindRoom 返回时调用 room-recorder。','规则是“应该加什么”的说明；选中它，才知道要把哪个记录包加入项目。',1,'教学规则 room-rule.json · 缩写','{\n  "ImportPath": "example.com/room",\n  "Function": "FindRoom",\n  "OnExit": "afterFindRoom",\n  "Path": "example.com/room-recorder"\n}',[2,4,5],[prepPanel('第一次匹配结果 B1','room 规则','new'),prepPanel('准备下一轮加入','room-recorder','new'),prepPanel('现在的缺口','规则选出来了，配套包还没接入','error')],'如果现在就结束循环，选中的记录包还没有被 newDeps 处理。'),
  prepFrame('准备②：接入 room-recorder，又带来了 cache','按 B1 生成记录包的 import 并同步依赖。这个教学记录包会调用 cache.Hit，所以 cache 也进入了构建。','依赖就是“这段代码还需要哪些其他代码”。加入一个包，可能把它用到的包一起带进来。',2,'room-recorder/record.go · 教学片段','package roomrecorder\n\nimport "example.com/cache"\n\nfunc afterFindRoom(/* 参数省略 */) {\n    cache.Hit("room:42")\n}',[3,6],[prepPanel('新加入的记录包','room-recorder','new'),prepPanel('跟着进入构建的包','cache','new'),prepPanel('当前规则集合','仍是第一次选出的 B1')],'第一次匹配时还看不到 cache；现在构建清单变了，需要重新检查规则。'),
  prepFrame('匹配②：新出现的 cache 也命中一条规则','重新扫描更新后的构建范围，找到 cache.Hit 的教学规则。最终集合 B2 有 room 和 cache 两条规则。','第二次匹配解决的是：第一次接入记录代码后，构建里新增了什么、规则选择有没有变化。',3,'教学规则 cache-rule.json · 缩写','{\n  "ImportPath": "example.com/cache",\n  "Function": "Hit",\n  "OnExit": "afterCacheHit",\n  "Path": "example.com/cache-recorder"\n}',[2,4,5],[prepPanel('第二次匹配结果 B2','room 规则 + cache 规则','new'),prepPanel('还需要接入','cache-recorder','new'),prepPanel('如果只做两轮','新选中的配套包还没补齐','error')],'第二次匹配结束，只得到了最终规则清单；清单对应的代码还要准备一次。'),
  prepFrame('准备③：把 B2 对应的记录包都补齐','再调用 newDeps(B2) 和 syncDeps。这次 room-recorder、cache-recorder 都接入，之后不再匹配。','新增规则是第二次匹配的产物，所以需要在它之后安排一次准备。',4,'otel.runtime.go · 展示本例的两个额外 import','package main\n\n// 基础 import 省略\nimport _ "example.com/room-recorder"\nimport _ "example.com/cache-recorder"',[4,5],[prepPanel('可以找到的记录代码','room-recorder + cache-recorder','ok'),prepPanel('最终规则','B2：room + cache','ok'),prepPanel('第三轮的动作','准备 → 同步；没有第 3 次匹配')],'对这个教学依赖链，构建所需代码已经备齐。三轮是当前实现固定的安排，并非 Go 的要求。'),
  prepFrame('现在才开始正式插桩构建','保存规则，然后启动带 toolexec 的构建：它在编译工具执行前接入改写。这里才会把前后动作接到目标函数。','前面解决“代码能不能找到”，这里解决“在目标函数什么位置调用它”。',5,'接入动作后的 FindRoom · 逻辑示意','func FindRoom(id int) Room {\n    result := originalFindRoom(id)\n    afterFindRoom(/* result 等参数 */)\n    return result\n}',[3],[prepPanel('前置准备','依赖与规则已经备齐','ok'),prepPanel('当前工作','改写编译输入 → 编译 → 链接'),prepPanel('得到的产物','带观察代码的业务二进制','new')],'这个包装只是帮助理解；真实实现使用生成的 trampoline（桥接函数）。'),
  prepFrame('启动程序，观察动作才随调用执行','部署并启动上一步的二进制，调用 FindRoom(42)，接入的记录动作随函数运行。','编译前准备和服务运行是两段时间；准备阶段负责让构建材料齐全，记录动作在运行时才执行。',5,'运行结果 · 教学示意','FindRoom(42)\n  → 查询房间\n  → afterFindRoom(...)\n      → cache.Hit("room:42")\n      → afterCacheHit(...)\n返回 Room{ID: 42}',[3,5],[prepPanel('业务结果','仍然返回房间 42','ok'),prepPanel('记录动作','room 与 cache 各自对应的动作'),prepPanel('观察这两件事','编译时准备代码；运行时调用代码')],'现在回看三轮：选出规则 → 补入代码 → 构建范围变化 → 重新选 → 补齐最终结果。')
];
const stopOne=prepFrame('试着只做一轮：缺了 room-recorder','第 1 轮是“准备基础库 → 匹配出 room 规则”。循环结束时，room 记录包还没有经过依赖准备。','newDeps 在 matchRules 前面执行；本轮新选出的规则，只能在下一轮才被 newDeps 处理。',1,'把循环展开成实际顺序 · 伪代码','newDeps([])\nsyncDeps()\nB1 = matchRules()\n// 在这里停止：没有 newDeps(B1)',[3,4],[prepPanel('选中的规则','room 规则','ok'),prepPanel('应有的配套代码','room-recorder 未准备','error'),prepPanel('假如继续构建','观察代码的依赖不完整','error')],'只做 1 轮，在这个例子里连第一次匹配的结果都还没准备。这里展示条件缺口，不是复制某次真实编译报错。');
const stopTwo=prepFrame('试着只做两轮：缺了 cache-recorder','第二轮把 room-recorder 带入，再发现 cache 规则，但 cache-recorder 还没准备。','再匹配得到的清单 B2，需要匹配之后的 newDeps(B2) 才能落实到构建输入里。',3,'把两轮展开 · 伪代码','newDeps([]); syncDeps()\nB1 = matchRules()\nnewDeps(B1); syncDeps()\nB2 = matchRules()\n// 在这里停止：没有 newDeps(B2)',[4,5],[prepPanel('已准备','room-recorder','ok'),prepPanel('最终新增的配套包','cache-recorder 未准备','error'),prepPanel('缺少的步骤','第三次准备与同步','error')],'如果第二次匹配没有任何相关变化，有的项目两轮可能就够；当前代码没有做这种提前结束的判断。');

export const focusDemos={
  preprocess:{
    title:'为什么是三轮？让一个房间查询亲自走一遍',
    scenario:'你要自动观察 FindRoom(42)。我们设置两条教学自定义规则：room 的记录包会调用 cache，而 cache 也有自己的记录包。先选“完整三轮”，每次点下一步，关注黄色标出的新增内容。',
    scope:'这是按 v1.15.0 控制流制作的教学模拟。example.com/* 为虚构模块；浏览器不执行 Go。真实上游例子见动画后的“源码里的同类情况”。',
    lanes:['准备① 基础库','匹配① 选 room','准备② 引入 cache','匹配② 选 cache','准备③ 补齐','正式构建 / 运行'],
    terms:[{term:'依赖',meaning:'这段代码要用到的其他代码，例如 room-recorder 用到了 cache。'},{term:'规则',meaning:'告诉工具“观察哪个函数、调用哪个记录函数”的配置。'},{term:'匹配',meaning:'查看实际参与构建的包，选出当前适用的规则。'},{term:'bundles / B1 / B2',meaning:'存放选中规则的清单；B1 是第一次结果，B2 是第二次结果。'}],
    cases:[{id:'full',label:'完整三轮',summary:'观察代码怎样逐次进入构建，最后再编译。',frames:prepFrames,verdict:'关键不在重复次数，而在依赖先后：newDeps 处理上次匹配的结果。两次匹配，前后需要安排三次准备。'},{id:'once',label:'只准备一轮会怎样？',summary:'停在第一次匹配后，看看缺什么。',frames:[...prepFrames.slice(0,3),stopOne],verdict:'第一次匹配才知道要接入 room-recorder；不能把匹配之前的那次准备，当成已经处理了匹配结果。'},{id:'twice',label:'只准备两轮会怎样？',summary:'停在第二次匹配后，看看这次又少了谁。',frames:[...prepFrames.slice(0,5),stopTwo],verdict:'第二次匹配可能产生新的记录包需求，第三次准备负责落实。当前代码固定三轮，没有检测是否还会继续出现新规则。'}],
    question:{prompt:'第二次匹配选出了 cache 规则，为什么后面还要调用 newDeps？',options:['要把新选中规则的记录包接入构建','每条请求必须生成三个 Span','Go 语言要求所有构建都循环三遍'],answer:0,explanation:'匹配只决定“要哪条规则”。依赖准备把规则用到的代码接进来。第二次匹配的产物，要由后面的第三次准备处理。'}
  },
  deps:{
    title:'工具装好了，为什么业务构建仍找不到记录函数？',
    scenario:'原来的 FindRoom(42) 能编译。你决定在返回后调用 afterFindRoom，但这个函数放在另一个 Go 包里。逐步把缺失的 import、require、replace 补齐。',
    scope:'代码与模块名是教学片段，省略完整 hook 签名与桥接；真实工具写入的路径和版本由源码计算。浏览器仅演示变化。',
    lanes:['业务代码','新增调用','定位包','补 go.mod','参与构建'],
    terms:[{term:'import',meaning:'Go 文件声明：这份代码要用哪个包。'},{term:'require',meaning:'go.mod 记录需要哪个模块的哪个版本。'},{term:'replace',meaning:'go.mod 指定这个模块实际到哪里找，例如本地目录。'}],
    cases:[{id:'normal',label:'补齐依赖',summary:'从一个新增记录动作，看编译需要哪些材料。',frames:[
      prepFrame('原来只需要 room 包','main 调用 FindRoom(42)，Go 可以找到 room，所以原来的代码能编译。','能编译旧代码，只能说明旧依赖齐全。',0,'main.go · 教学片段','import "example.com/room"\n\nfunc main() { room.FindRoom(42) }',[1],[prepPanel('原来的构建输入','main + room','ok'),prepPanel('还没有的代码','room-recorder','muted')],'普通构建可用；新加的记录动作尚未参与。'),
      prepFrame('现在多了一个记录动作','自动改写需要把 afterFindRoom 接在函数返回前。它来自 room-recorder。','Go 不会因为你把 otel 工具装进 PATH，就自动把工具里的库当成业务依赖。',1,'加工后的逻辑 · 不是实际桥接代码','result := room.FindRoom(42)\nroomrecorder.AfterFindRoom(result)',[2],[prepPanel('新增的调用','roomrecorder.AfterFindRoom','new'),prepPanel('现在的问题','记录包的代码在哪里？','error')],'需要先让业务构建能定位记录包。'),
      prepFrame('先在生成文件中引入包','LoongSuite 生成的 otel.runtime.go 会包含记录包的 import。下方用教学模块名表示。','import 把包放入构建范围；它本身不等于目标函数已经被插入调用。',2,'otel.runtime.go · 教学片段','package main\n\nimport _ "example.com/room-recorder"',[3],[prepPanel('生成的构建输入','记录包的 import','new'),prepPanel('接下来需要','把包名解析到模块位置')],'下划线 import 的意思是引入包，不在这个文件里直接使用它的普通名称。'),
      prepFrame('再说明去哪里找到模块','require 提供模块和版本；replace 指向已经准备好的本地代码。示例路径由人写，真实工具会计算。','包名不是磁盘位置；编译系统需要模块解析信息把两者连接起来。',3,'go.mod · 教学示例','module example.com/app\n\ngo 1.25.0\n\nrequire example.com/room-recorder v0.0.0\nreplace example.com/room-recorder => ../room-recorder',[5,6],[prepPanel('需要的模块','room-recorder v0.0.0','new'),prepPanel('实际代码位置','../room-recorder','new')],'v0.0.0 只是本例占位；本指南源码页给出了上游实际使用的占位版本。'),
      prepFrame('代码和模块信息都能对应了','Go 读到生成的 import，按 go.mod 找到记录包及它需要的其他包。syncDeps 调用 go mod tidy 整理实际依赖。','这样后续编译输入中新加的观察代码才有机会通过解析和链接。',4,'本例的解析路径 · 示意','新增的观察动作\n  → import example.com/room-recorder\n  → require + replace\n  → ../room-recorder 的 Go 源码\n  → 编译并链接',[2,3,4],[prepPanel('目标函数','要接入的动作已确定','ok'),prepPanel('配套代码','可以找到并参与构建','ok')],'先解决依赖，再检查规则命中、签名和链接；找到包不代表整个插桩过程已经成功。')
    ],verdict:'工具是加工者；记录包是要进入业务产物的代码。二者的依赖范围不同，所以需要给业务构建补材料。'}],
    question:{prompt:'写了记录包的 import 后，是否就代表目标函数会自动产生 Span？',options:['是，import 自带插桩能力','还不够，还要规则命中、改写和运行时记录','只需要再生成一个 Trace ID'],answer:1,explanation:'import 负责把代码接入构建范围。目标函数还需要命中规则并成功接入调用；运行时也要有正确的记录和上报配置。'}
  }
};
